public interface IClock { static abstract DateTime UtcNow { get; } }   // C# 11
public sealed class Job<TClock> where TClock : IClock                 // no policy storage
{
    public static DateTime Next() => TClock.UtcNow;
}
public sealed class SystemClock : IClock
{
    public static DateTime UtcNow => DateTime.UtcNow;
}
